    swingActive: false,
    inning: 1,
    strikes: 0,
    balls: 0
  };
}

function updateBaseball() {
  // Update ball position
  const b = gameState.baseball;
  b.ball.x += b.ball.vx;
  b.ball.y += b.ball.vy;

  // Pitch logic
  if (b.pitchType === 'fastball') {
    b.ball.vx = 15;
  }

  // Update DOM
