input.newString:
/* Responsive */
@media (max-width: 600px) {
  .menu-options .btn-sport,
  .menu-options .btn-option {
    width: 100%;
    margin: 5px 0;
  }

  .creator-controls {
    align-items: center;
  }
}

/* HUD Buttons */
.hud {
  position: absolute;
  bottom: 0;
  width: 100%;
  padding: 15px;
  background: rgba(26, 26, 26, 0.8);
  backdrop-filter: blur(10px);
  border-top: 2px solid var(--wii-blue);
  display: flex;
  gap: 10px;
  justify-content: center;
  flex-wrap: wrap;
  z-index: 100;
}

.hud-btn {
  display: inline-block;
  padding: 10px 20px;
  font-size: 13px;
  font-weight: bold;
  border: none;
  border-radius: 6px;
  cursor: pointer;
  transition: all 0.15s;
  background: var(--bg-medium);
  color: var(--fg-light);
  min-width: 120px;
  text-align: center;
  white-space: nowrap;
  border: 1px solid var(--fg-muted);
}

.hud-btn:hover {
  background: var(--wii-blue);
  border-color: var(--wii-blue);
  transform: translateY(-2px);
  box-shadow: 0 4px 12px rgba(58, 151, 217, 0.4);
}

.hud-btn:active {
  transform: translateY(0);
  background: var(--wii-blue-dark);
}

.hud-btn.hud-activated {
  background: var(--wii-yellow);
  color: var(--bg-dark);
  transform: scale(0.98);
  box-shadow: inset 0 2px 4px rgba(0,0,0,0.2);
}

.hud-btn:focus-visible {
  outline: 2px solid var(--wii-yellow);
  outline-offset: 2px;
}

/* Sport-specific HUD groupings */
.hud-pitching,
.hud-batting,
.hud-clubs,
.hud-spin,
.hud-power {
  display: flex;
  flex-direction: column;
  gap: 8px;
  align-items: center;
}

.hud-pitching > .hud-btn,
.hud-batting > .hud-btn,
.hud-clubs > .hud-btn,
.hud-spin > .hud-btn,
.hud-power > .hud-btn {
  min-width: 110px;
}

/* Tennis HUD */
.tennis-btn {
  background: var(--wii-green);
  color: white;
  border-color: var(--wii-green);
}

.tennis-btn:hover {
  background: #54c466;
  box-shadow: 0 4px 12px rgba(115, 173, 33, 0.4);
}

/* Baseball HUD */
.baseball-btn {
  background: var(--wii-red);
  color: white;
  border-color: var(--wii-red);
}

.baseball-btn:hover {
  background: #e84118;
  box-shadow: 0 4px 12px rgba(228, 26, 28, 0.4);
}

/* Golf HUD */
.golf-btn {
  background: var(--wii-orange);
  color: white;
  border-color: var(--wii-orange);
}

.golf-btn:hover {
  background: #ff7c40;
  box-shadow: 0 4px 12px rgba(255, 107, 53, 0.4);
}

/* Bowling HUD */
.bowling-btn {
  background: var(--wii-blue);
  color: white;
  border-color: var(--wii-blue);
}

.bowling-btn:hover {
  background: #5a9fd8;
  box-shadow: 0 4px 12px rgba(58, 151, 217, 0.4);
}

/* Boxing HUD */
.box-btn {
  background: var(--wii-red);
  color: white;
  border-color: var(--wii-red);
}

.box-btn:hover {
  background: #e84118;
  box-shadow: 0 4px 12px rgba(228, 26, 28, 0.4);
}

